function toBigInt(value) {
  return typeof value === 'bigint' ? value : BigInt(value);
}

export function b58encodeInt(value, defaultOne = true) {
  let current = toBigInt(value);

  if (current === 0n && defaultOne) {
    return BITCOIN_ALPHABET[0];
  }

  let encoded = '';

  while (current !== 0n) {
    const { quotient, remainder } = divmodFloor(current, BASE_58);
    current = quotient;
    encoded = BITCOIN_ALPHABET[Number(remainder)] + encoded;
  }

  return encoded;
}

export function b58decodeInt(value) {
  const text = scrubAsciiInput(value);
  let decoded = 0n;

  for (const character of text) {
    const digit = BITCOIN_LOOKUP[character];

    if (digit === undefined) {
      throw new ValueError(`Invalid character '${character}'`);
    }

    decoded = (decoded * BASE_58) + digit;
  }

  return decoded;
}

import { BASE58_ALPHABET, BASE58_BASE, BASE58_INDEX } from './alphabet.mjs';
