export function encodeBase58Int(value) {
  if (value < 0n) {
    throw new RangeError('Negative integers are not supported by this port.');
  }

  if (value === 0n) {
    return BASE58_ALPHABET[0];
  }

  let remaining = value;
  let encoded = '';

  while (remaining > 0n) {
    const digit = Number(remaining % BASE58_BASE);
    encoded = BASE58_ALPHABET[digit] + encoded;
    remaining /= BASE58_BASE;
  }

  return encoded;
}

export function decodeBase58Int(value) {
  const scrubbedValue = scrubBase58Input(value);
  let decoded = 0n;

  for (const character of scrubbedValue) {
    const digit = BASE58_INDEX.get(character);

    if (digit === undefined) {
      throw new ValueError(`Invalid character ${formatPythonStringLiteral(character)}`);
    }

    decoded = decoded * BASE58_BASE + BigInt(digit);
  }

  return decoded;
}

