const TRAILING_ASCII_WHITESPACE = /[ \t\n\r\f\v]+$/u;

function formatPythonCharacterEscape(character) {
  const codePoint = character.codePointAt(0);

  if (codePoint <= 0xff) {
    return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  }

  if (codePoint <= 0xffff) {
    return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  }

  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

export function scrubBase58Input(value) {
  let position = 0;

  for (const character of value) {
    if (character.codePointAt(0) > 0x7f) {
      throw new UnicodeEncodeError(
        `'ascii' codec can't encode character '${formatPythonCharacterEscape(
          character,
        )}' in position ${position}: ordinal not in range(128)`,
      );
    }

    position += 1;
  }

  return value.replace(TRAILING_ASCII_WHITESPACE, '');
}

