function looksLikeOptionToken(token) {
  return typeof token === 'string' && token.length > 1 && token.startsWith('-');
}

function formatUsage(programName, optionDefinitions) {
  const requiredOptions = optionDefinitions.map((definition) => `${definition.flag} ${definition.metavar}`);
  return `usage: ${programName} [-h] ${requiredOptions.join(' ')}\n`;
}

function formatHelp(programName, optionDefinitions) {
  const optionLines = optionDefinitions.map((definition) => `  ${definition.flag} ${definition.metavar}\n`).join('');

  return `${formatUsage(programName, optionDefinitions)}\noptions:\n  -h, --help  show this help message and exit\n${optionLines}`;
}

function createError(programName, optionDefinitions, message) {
  return new CliExit(2, 'stderr', `${formatUsage(programName, optionDefinitions)}${programName}: error: ${message}\n`);
}

function parseOptionValue(rawValue, definition, programName, optionDefinitions) {
  if (definition.type === 'int') {
    const parsedValue = parsePythonIntLiteral(rawValue);

    if (parsedValue === null) {
      throw createError(programName, optionDefinitions, `argument ${definition.flag}: invalid int value: '${rawValue}'`);
    }

    return parsedValue;
  }

  return rawValue;
}

export function parseLongOptions(argv, optionDefinitions) {
  const programName = getProgramName(argv);
  const tokens = Array.isArray(argv) ? argv.slice(2) : [];
  const parsedValues = Object.create(null);
  const extras = [];
  const definitionsByFlag = new Map(optionDefinitions.map((definition) => [definition.flag, definition]));

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (token === '-h' || token === '--help') {
      throw new CliExit(0, 'stdout', formatHelp(programName, optionDefinitions));
    }

    if (token === '--') {
      extras.push(...tokens.slice(index + 1));
      break;
    }

    if (!looksLikeOptionToken(token)) {
      extras.push(token);
      continue;
    }

    const equalsIndex = token.indexOf('=');
    const flag = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
    const definition = definitionsByFlag.get(flag);

    if (!definition) {
      extras.push(token);

      if (equalsIndex === -1 && index + 1 < tokens.length) {
        const nextToken = tokens[index + 1];

        if (!looksLikeOptionToken(nextToken) || isNegativeNumberToken(nextToken)) {
          extras.push(nextToken);
          index += 1;
        }
      }

      continue;
    }

    let rawValue;

    if (equalsIndex !== -1) {
      rawValue = token.slice(equalsIndex + 1);
    } else {
      if (index + 1 >= tokens.length) {
        throw createError(programName, optionDefinitions, `argument ${definition.flag}: expected one argument`);
      }

      const nextToken = tokens[index + 1];

      if (looksLikeOptionToken(nextToken) && !isNegativeNumberToken(nextToken)) {
        throw createError(programName, optionDefinitions, `argument ${definition.flag}: expected one argument`);
      }

      rawValue = nextToken;
      index += 1;
    }

    parsedValues[definition.name] = parseOptionValue(rawValue, definition, programName, optionDefinitions);
  }

  const missingDefinitions = optionDefinitions.filter((definition) => definition.required && !(definition.name in parsedValues));

  if (missingDefinitions.length > 0) {
    const missingFlags = missingDefinitions.map((definition) => definition.flag).join(', ');
    throw createError(programName, optionDefinitions, `the following arguments are required: ${missingFlags}`);
  }

  if (extras.length > 0) {
    throw createError(programName, optionDefinitions, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return parsedValues;
}

